    : { built: false, progress: Math.max(0, Math.min(1, (day - b.start) / (b.done - b.start))) };
}

function lastWord(round, mission, losses) {
  if (round.id !== 'artemis-4') return LAST_WORD[round.id] || '';
  // The traverse call only happens once the crew is out on the surface.
  const decisions = mission?.decisions;
  const walked = Array.isArray(decisions) && decisions.some(d => d?.id === 'traverse');
  const walk = walked ? 'Artemis IV’s crew walked near the south pole of the Moon. ' : '';
  const end = LAST_WORD[round.id];
  if (mission?.fate === 'killed') return `${walk}The crew was lost. ${end}`;
  if (losses?.some(loss => loss.round === round.id)) return `${walk}Members of the crew were lost. ${end}`;
  if (mission?.fate === 'hurt')
    return `${walk}The crew returned with injuries${walked ? '' : ' without landing on the Moon'}. ${end}`;
  if (mission?.fate === 'safe')
    return `${walk}The crew came home safely${walked ? '' : ' without landing on the Moon'}. ${end}`;
  return `${walk}${end}`;
}

function craftAt(craft, day) {
  const L = craft.legs;
  if (day <= L[0].day) return planetAt(L[0].planet, day);
  for (let i = 0; i < L.length - 1; i++) {
    const a = L[i],
      b = L[i + 1];
    if (day > b.day) continue;
    const [a0, r0] = planetAt(a.planet, a.day),
      [a1, r1] = planetAt(b.planet, b.day);
    let sweep = a1 - a0;
    while (sweep <= 0.2) sweep += Math.PI * 2;
    const k = (day - a.day) / (b.day - a.day),
      ease = k * k * (3 - 2 * k);
    const loop = a.planet === b.planet || r1 < r0 ? Math.sin(Math.PI * k) * 0.25 * Math.max(r0, r1) : 0;
    return [a0 + sweep * k, r0 + (r1 - r0) * ease + loop];
  }
  const last = L[L.length - 1];
  if (last.what !== 'flyby') return planetAt(last.planet, day);
  const [a, r] = planetAt(last.planet, last.day);
  return [a + 0.02 * Math.log1p((day - last.day) / 365), r + ((day - last.day) / 365) * 3.5];
}

function planetAt(id, day) {
  const p = PLANETS[id];
  const deg = p.L0 + (360 / p.P) * (day - J2000);
  return [(((deg % 360) + 360) % 360) * (Math.PI / 180), p.au];
}

function routeReach(id) {
  const routes = ROUTES[id] || [];
  return Math.max(1.6, ...routes.flatMap(c => c.legs.map(l => PLANETS[l.planet].au)));
}

function fixerOf(vehicle, cause) {
  const f = FIXERS[vehicle] || FIXERS.redstone;
  if (!cause || cause === 'nominal' || cause === 'unknown') return f.all;
  return f.by[cause] || f.booster;
}

function powerPlan(on) {
  const t = powerTotal(on);
  if (t.over) return 'over';
  if (!on.guidance) return 'blind';
  if (!['quads', 'voice', 'displays'].every(k => on[k])) return 'cold';
  return on.telemetry && on.early ? 'clean' : 'margin';
}

function powerTotal(on) {
  const used = Object.keys(POWER_SYSTEMS)
    .filter(k => on[k])
    .reduce((a, k) => a + POWER_SYSTEMS[k].ah, 0);
  const budget = POWER_BUDGET + (on.topup ? TOPUP.ah : 0);
  return { used, budget, over: used > budget };
}

function cardsFor(record, c) {
  if (!c || c.kind === 'sim' || !record?.cards) return [];
  const phase = phaseOf(c);
  const out = [];
  for (const key of Object.keys(record.cards)) {
    const card = SIM_CARDS[key];
    if (card && card.phase === phase && !out.includes(card.text)) out.push(card.text);
  }
  return out;
}

function earnCard(record, scenario, day) {
  const card = SIM_CARDS[scenario];
  if (!card) return null;
  record.cards = record.cards || {};
  const fresh = !record.cards[scenario];
  if (fresh) record.cards[scenario] = { day };
  return fresh ? card.text : null;
}

